from collections import deque, Counter
# component extract non-background source on r0:11 (maybe end r10; row11 empty)
def comps(grid, predicate, connectivity=8):
    R,C=len(grid),len(grid[0]); seen=set(); out=[]
    neigh=[(dr,dc) for dr in (-1,0,1) for dc in (-1,0,1) if (dr or dc) and (connectivity==8 or abs(dr)+abs(dc)==1)]
    for r in range(R):
      for c in range(C):
        if (r,c) in seen or not predicate(r,c): continue
        q=[(r,c)]; seen.add((r,c)); cells=[]
        while q:
          x,y=q.pop(); cells.append((x,y))
          for dr,dc in neigh:
            a,b=x+dr,y+dc
            if 0<=a<R and 0<=b<C and (a,b) not in seen and predicate(a,b): seen.add((a,b));q.append((a,b))
        r0=min(x for x,y in cells); c0=min(y for x,y in cells)
        shape=tuple(sorted((x-r0,y-c0,grid[x][y]) for x,y in cells))
        out.append((len(cells),(r0,c0),(max(x for x,y in cells)-r0+1,max(y for x,y in cells)-c0+1),shape,cells))
    return sorted(out,key=lambda x:(x[1][0],x[1][1]))
